class R { static string root; static int Main(){ root=@"F:\vam1.22.0.12"; AppDomain.CurrentDomain.AssemblyResolve += Resolve; var a=Assembly.LoadFrom(Path.Combine(Path.Combine(Path.Combine(root,"VaM_Data"),"Managed"),"Assembly-CSharp.dll")); foreach(string n in new[]{"MVRPluginManager","DAZCharacterSelector","SuperController","Atom","JSONStorable","DAZClothingItem","DAZDynamicItem"}) { Console.WriteLine("---"+n+"---"); var t=a.GetType(n); foreach(var m in t.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly)){ if(n!="SuperController" || m.Name.IndexOf("HUD",StringComparison.OrdinalIgnoreCase)>=0 || m.Name.IndexOf("SelectController",StringComparison.OrdinalIgnoreCase)>=0) Console.WriteLine(m); } } return 0; }
